# Generated from a fixture by the schematic editor (varimu.editor): edit the drawing, not this file.

title: 'Fairchild 670, one channel: generated by varimu.circuit.netlist'

input: in

probes: [out, cv, tcb, bp, ga, gb, ka, kb, ur, sg, nb2, nb3, nb4, in_s]

controls:
  input_atten_db: {value: 11.0, min: 0.0, max: 30.0, unit: dB, source: 'sch: AT101 600 ohm T attenuator; [MAN] p.5 1 dB/step. Default: the factory adjustment''s unity gain (above; [MAN] p.9 says ~10 dB). Range end (30 dB) is provisional: step count not legible'}
  ac_threshold: {value: 0.709, min: 0.0, max: 1.0, unit: rotation, source: 'sch: R115A / R115B dual tapped pot (front-panel knob; values below). Default: the factory adjustment (above)', notes: 'the wipers'' fraction of the track from the centre line: 0 = no signal to the sidechain (the manual''s ''fully CCW'', curve 1), 1 = the whole T103 secondary = lowest threshold'}
  time_constant: {value: 2, min: 1, max: 6, unit: position, source: 'sch: S102 positions 1-6'}
  dc_threshold: {value: 0.253, min: 0.0, max: 1.0, unit: rotation, source: 'sch: R117 100k (screwdriver beneath front panel). Default: the factory adjustment (above)', notes: '0 = 12AX7 cathodes at ~3.6 V (lowest threshold; the manual''s ''fully CW'', curves 4 and 5), 1 = ~16 V'}
  balance: {value: 0.5, min: 0.0, max: 1.0, unit: rotation, source: 'sch: R105A/B dual 100 ohm (screwdriver, front panel)'}
  zero: {value: 0.3, min: 0.0, max: 1.0, unit: rotation, source: 'sch: R142 2500 ohm ''ZERO'' between the bias supply''s C108 node and ground (data/schematics/fairchild_670/README.md, supply rails). [MAN] p.7 sets it for a meter zero in S101''s ZERO position, where the meter reads 15 ohm x the stage''s total plate current; 0.3 idles each bank at 24.9 mA (scripts/calibrate_psu.py, 2026-10-21), against ~26 mA measured (web: https://groupdiy.com/threads/fairchild-670-questions.32169/)', notes: standing 6386 grid bias = zero * the C108 node's voltage}
  b_plus_adj: {value: 0.725, min: 0.0, max: 1.0, unit: rotation, source: 'sch: R313 250K ''B+ ADJ'' (screwdriver, inside); [MAN] p.7: adjust only if pin 8 of V302 deviates from 240 V. Set so the settled rail is 240.0 V at the nominal genome (scripts/calibrate_psu.py, 2026-10-21)', notes: '0 = wiper at R312 (240 V side): the 6084 grid highest, the output lowest'}
  mains_v_rms: {value: 117.0, min: 100.0, max: 127.0, unit: V, source: '[MAN] p.4: power 117 volts; stable over line voltage 100 to 127 volts'}
  mains_hz: {value: 60.0, min: 50.0, max: 60.0, unit: Hz, source: '[MAN] p.4: 50-60 cycles'}

values:
  t101_c_half_f: {value: 1.0e-10, genome: transformers.input.winding_capacitance_f, source: 'provisional: model knowledge (high-ratio input transformer secondaries, 50-200 pF)'}
  t102_c_half_f: {value: 2.0e-10, genome: transformers.output.winding_capacitance_f, source: 'provisional: model knowledge (push-pull output primaries, 100-500 pF)'}
  t103_c_half_f: {value: 1.0e-10, genome: transformers.sidechain_input.winding_capacitance_f, source: 'provisional: model knowledge (secondaries of a small step-up transformer, 50-200 pF)'}
  t104_c_half_f: {value: 2.0e-10, genome: transformers.sidechain_output.winding_capacitance_f, source: 'provisional: model knowledge (push-pull primaries, 100-500 pF)'}
  t104_c_sec_f: {value: 1.0e-10, genome: transformers.sidechain_output.secondary_capacitance_f, source: 'provisional: model knowledge (self-capacitance of a 600 ohm line winding, as the EQP-1A''s HS-56)', notes: 'across the secondary (the bridge''s ay / bk): it takes the leakage''s current when the bridge cuts off (the pre-flight rectifier check; added 2026-10-26, the user''s choice)'}
  t101_turns_half: {value: 4.5, genome: transformers.input.turns_ratio, source: 'web: https://www.don-audio.com/Sowter-8346E-Fairchild-Signal-amp-input-transformer-T101-201 (replacement: 600:50k, 1+1:9+9) -> each secondary half = 4.5x the series primary'}
  t101_r_pri_ohm: {value: 20.0, source: 'provisional: model knowledge (series primary of a 600 ohm line transformer)'}
  t101_r_half_ohm: {value: 400.0, source: 'provisional: model knowledge (each half of a 50k secondary)'}
  t101_core_material: {value: mumetall, genome: transformers.input.core_material, source: 'web: https://www.don-audio.com/Sowter-8346E-Fairchild-Signal-amp-input-transformer-T101-201 (the replacement has a mumetal core); the original''s is not documented'}
  t101_core_area_m2: {value: 0.0001, genome: transformers.input.core_area_m2, source: 'provisional: model knowledge (line input transformer core, ~1 cm^2; the replacement''s can is 45 x 72 x 63 mm, same page)'}
  t101_core_path_m: {value: 0.07, genome: transformers.input.core_path_m, source: 'provisional: model knowledge (E-I core of that size)'}
  t101_gap_m: {value: 1.0e-05, genome: transformers.input.air_gap_m, source: 'provisional: model knowledge (butt joints of a stacked, ungapped core; no DC in T101)'}
  t101_turns: {value: 1320, genome: transformers.input.turns, source: 'provisional: derived (gave the former 10 H primary at nominal geometry and gap with mumetall''s origin permeability then, 5,850; 17.7 H in the linear limit since the 2026-10-24 refit, see the transformer notes above)', notes: series primary (the reference winding)}
  t101_leakage_h: {value: 0.0025, genome: transformers.input.leakage_h, source: 'provisional: chosen so the slice meets the published 40 Hz - 15 kHz +-1 dB (web: https://www.telefunken-elektroakustik.com/product/fairchild-670, reissue/dealer specs): measured 2026-10-21 with ngspice .ac on the linear-core build, -0.4 dB at 40 Hz, +0.2 dB at 15 kHz, the T101 secondary resonance at 35.5 kHz (+1.4 dB). The slice''s former k = 0.999 (20 mH) gave +15 dB at 17.8 kHz once the lumped loss resistors were gone', notes: referred to the primary (0.2 H referred to the 50k secondary)}
  t101_c_interwinding_f: {value: 0.0, genome: transformers.input.interwinding_capacitance_f, source: 'provisional: nominal 0 = electrostatically screened (unknown for the original; unscreened line transformers have tens of pF)', notes: 'half from each grid end of the secondary to the primary hot end (balanced). 20 pF here plus 50 pF on T102 made the 6386 stage oscillate at ~31 kHz at idle (tuned-plate tuned-grid; measured 2026-10-21): the plausibility checks (Phase 4) must catch such units'}
  v6386_per_side: {value: 4, source: 'sch: V101A/V102A + V103B/V104B on one side, V101B/V102B + V103A/V104A on the other'}
  t102_turns_half: {value: 4.5, genome: transformers.output.turns_ratio, source: 'web: https://don-audio.com/Sowter-8344e-Fairchild-Signal-amp-output-transformer-T102-202 (replacement: 60k CT:600, 9+9:1+1) -> each primary half = 4.5x the series secondary'}
  t102_r_half_ohm: {value: 150.0, source: 'provisional: model knowledge (each half of a 60k CT primary)'}
  t102_r_sec_ohm: {value: 10.0, source: 'provisional: model knowledge (600 ohm secondary)'}
  t102_core_material: {value: grain_oriented_si_steel, genome: transformers.output.core_material, source: 'web: https://don-audio.com/Sowter-8344e-Fairchild-Signal-amp-output-transformer-T102-202 (the replacement has an M6 core, grain-oriented steel); the original''s is not documented'}
  t102_core_area_m2: {value: 0.0002, genome: transformers.output.core_area_m2, source: 'provisional: model knowledge (the replacement''s can is 48.5 mm dia x 57 mm, same page)'}
  t102_core_path_m: {value: 0.09, genome: transformers.output.core_path_m, source: 'provisional: model knowledge (E-I core of that size)'}
  t102_gap_m: {value: 2.0e-05, genome: transformers.output.air_gap_m, source: 'provisional: model knowledge (butt joints of a stacked core; push-pull, so no deliberate gap)'}
  t102_turns: {value: 360, genome: transformers.output.turns, source: 'provisional: derived (gives the former 30 H per primary half at nominal geometry and gap, see the transformer notes above)', notes: series secondary (the reference winding); each primary half has 4.5x}
  t102_leakage_h: {value: 0.003, genome: transformers.output.leakage_h, source: 'provisional: model knowledge (keeps the slice''s k = 0.999: 2 (1 - k) x 1.48 H)', notes: referred to the secondary}
  t102_c_interwinding_f: {value: 0.0, genome: transformers.output.interwinding_capacitance_f, source: 'provisional: nominal 0 = electrostatically screened (unknown for the original; unscreened output transformers have tens to 100+ pF)', notes: half from each plate end to the output (balanced); see t101_c_interwinding_f}
  t103_turns_half: {value: 8.5, genome: transformers.sidechain_input.turns_ratio, source: 'web: https://www.sowter.co.uk/acatalog/VINTAGE-COMPRESSOR-TRANSFORMERS-A-to-K.html (replacement 8345E: 600 ohms/170k ohms, ratio 17+17:1+1) -> each secondary half = 8.5x the series primary (the two pads feed one primary here); the original''s ratio isn''t printed'}
  t103_core_material: {value: mumetall, genome: transformers.sidechain_input.core_material, source: 'web: same page (the replacement has a mumetal core); the original''s is not documented'}
  t103_core_area_m2: {value: 5.0e-05, genome: transformers.sidechain_input.core_area_m2, source: 'provisional: model knowledge (small signal transformer core)'}
  t103_core_path_m: {value: 0.05, genome: transformers.sidechain_input.core_path_m, source: 'provisional: model knowledge'}
  t103_gap_m: {value: 1.0e-05, genome: transformers.sidechain_input.air_gap_m, source: 'provisional: model knowledge (butt joints; no DC)'}
  t103_turns: {value: 1215, genome: transformers.sidechain_input.turns, source: 'provisional: derived (gave the former 5 H primary at nominal geometry and gap with mumetall''s origin permeability then, 5,850; 7.9 H in the linear limit since the 2026-10-24 refit, see the transformer notes above)', notes: 'series primary (the reference winding); each secondary half has t103_turns_half times as many (10,330 at 8.5). The primary inductance doesn''t depend on the ratio, so the ratio change (2026-10-23) left this value'}
  t103_leakage_h: {value: 0.005, genome: transformers.sidechain_input.leakage_h, source: 'provisional: chosen so T103 standalone (its pads in front, the threshold pots'' load behind) is within 0.5 dB from 40 Hz to 20 kHz, the era''s rating for line-to-grid transformers (web: https://www.worldradiohistory.com/Archive-Electronics/40s/Electronics-1949-07.pdf, UTC''s advertisement: +-1 dB 20-20,000 cycles; the replacement''s response isn''t published). Measured 2026-10-23: -0.20 / +0.08 / -0.45 dB at 40 Hz / 15 / 20 kHz. The former 10 mH (k = 0.999) gave -2.1 dB at 15 kHz once the ratio became 8.5 (it is 72x that referred to a secondary half)', notes: referred to the primary}
  ac_threshold_tap: {value: 0.5, genome: sidechain_threshold.pot_tap, source: 'web: same thread (CJ: ''i think it would have to be a 50% tap''); the drawing doesn''t show where the tap is', notes: fraction of each section's track from its centre-line end}
  t104_sec_per_half: {value: 0.5, genome: transformers.sidechain_output.turns_ratio, source: 'web: https://don-audio.com/9643S-Fairchild-Control-amp-output-T104-204 (replacement: 10k CT:600, 4:1) -> secondary = half a primary half'}
  t104_fb_per_half: {value: 0.2105, source: 'web: same page, feedback winding 9.5:1 of the full primary'}
  t104_core_material: {value: grain_oriented_si_steel, genome: transformers.sidechain_output.core_material, source: 'web: https://don-audio.com/9643S-Fairchild-Control-amp-output-T104-204 (the replacement is M6 cored); the original''s is not documented'}
  t104_core_area_m2: {value: 0.0004, genome: transformers.sidechain_output.core_area_m2, source: 'provisional: model knowledge (the replacement weighs 1.2 kg, same page: a 2 x 2 cm core cross-section is typical at that weight)'}
  t104_core_path_m: {value: 0.12, genome: transformers.sidechain_output.core_path_m, source: 'provisional: model knowledge (E-I core of that size)'}
  t104_gap_m: {value: 2.0e-05, genome: transformers.sidechain_output.air_gap_m, source: 'provisional: model knowledge (butt joints; push-pull, so no deliberate gap)'}
  t104_turns: {value: 670, genome: transformers.sidechain_output.turns, source: 'provisional: derived (gives the former 10 H per primary half at nominal geometry and gap)', notes: each primary half (the reference winding)}
  t104_leakage_h: {value: 0.02, genome: transformers.sidechain_output.leakage_h, source: 'provisional: model knowledge (keeps the slice''s k = 0.999: 2 (1 - k) x 10 H)', notes: referred to a primary half}
  bridge_diode: {value: SI_RECTIFIER, source: 'sch: CR101-104 1N538 silicon; modeled with config/devices/si_rectifier.yaml (provisional 1N4007-like)'}
  rectifier_tube: {value: GZ34, source: 'sch: V301 printed ''6234'', which is the GZ34: [MAN] p.5 tube complement ''1-GZ34 (5V4)'', p.2 chassis photo label ''GZ34 (5AR4)''; config/devices/gz34.yaml (per anode)'}
  selenium_c_f_per_in2: {value: 1.25e-07, source: 'Sarkes Tarzian handbook (1950) p.54: ''the approximate capacity ranges from .1 to .15 microfarads per square inch of rectifying area'' (the middle; data/datasheets/published_points.yaml)', notes: across each GR301 arm}
  gr301_cell_area_in2: {value: 1.0, genome: psu.gr301_cell_area_in2, source: 'provisional: Sarkes Tarzian handbook (1950) p.61 ratings: a bridge of 1-inch-square cells (size 2) carries 0.225 A continuous, 80% into a capacitor, the smallest size above the ~0.14 A this bias supply draws; GR301''s cells aren''t documented', notes: 'rectifying area per arm; one cell per arm (Tarzian''s 26 V AC bridge, code 1B1)'}
  bias_rectifier: {value: SELENIUM, source: 'sch: GR301 bridge (selenium: web: https://www.radiomuseum.org/r/fairchild_stereo_limiter_670.html; Sowter 0531 notes ''the original Selenium bridge rectifier''); config/devices/selenium.yaml per arm'}
  passive_seed: {value: 0, genome: passives.seed, source: 'numerical: which set of parts a unit is built from'}
  passive_spread: {value: 0.0, genome: passives.spread, source: 'provisional: fraction of each part''s tolerance band its deviation spans (0 = every part at its printed value)'}
  tol_resistor_unmarked_pct: {value: 10.0, source: 'sch: note 1, ''RESISTORS DESIGNATED IN OHMS, 10% & 1/2W UNLESS OTHERWISE SPECIFIED'''}
  tol_pot_pct: {value: 20.0, genome: passives.pot_pct, source: 'provisional: model knowledge (carbon and wirewound potentiometers of the era, +-10..20% track resistance)'}
  tol_attenuator_pct: {value: 2.0, genome: passives.attenuator_pct, source: 'provisional: model knowledge (a precision step attenuator, +-1..5% per resistor)'}
  tol_paper_pct: {value: 20.0, genome: passives.paper_capacitor_pct, source: 'provisional: model knowledge (paper and oil capacitors of the 1950s, +-10..20%)'}
  tol_mica_pct: {value: 10.0, genome: passives.mica_capacitor_pct, source: 'provisional: model knowledge (high-voltage mica or ceramic, +-5..20%)'}
  tol_electrolytic_minus_pct: {value: 20.0, genome: passives.electrolytic_minus_pct, source: 'provisional: model knowledge (1950s electrolytics, -10..-20%)'}
  tol_electrolytic_plus_pct: {value: 50.0, genome: passives.electrolytic_plus_pct, source: 'provisional: model knowledge (1950s electrolytics, +50..+100%)'}
  tube_emission_pct: {value: 10.0, genome: tubes.instance.emission_pct, source: 'provisional: model knowledge (plate current of new tubes of one type at fixed bias, +-10..20%)'}
  tube_mu_pct: {value: 3.0, genome: tubes.instance.mu_pct, source: 'provisional: model knowledge (grid-pitch tolerance, a few %)'}
  attenuator_z_ohm: {value: 600, source: 'sch: AT101 600 ohm T'}
  c101_f: {value: 4.0e-06, source: 'sch: C101/C102 4 uF 200 V; sch-interp: between the two bank cathode nodes'}
