  c105_c106_f: {value: 2.0e-11, source: 'sch: C105 ''20 NMF'', C107(V108) ''20 MMF'' 1.6 kV; read as 20 pF'}
  c107_c108_f: {value: 1.0e-07, source: 'sch: C107, C108 .1 600V'}
