  l301_h: {value: 10.0, source: 'web: https://www.sowter.co.uk/acatalog/VINTAGE-COMPRESSOR-TRANSFORMERS-A-to-K.html (replacement L301: 10 H, 200 mA, 71 ohms); not printed on A-96039', genome: psu.l301_h}
  l301_r_ohm: {value: 71.0, source: 'web: same page (71 ohms)', genome: psu.l301_r_ohm}
  l302_h: {value: 5.0, source: 'web: https://www.sowter.co.uk/acatalog/VINTAGE-COMPRESSOR-TRANSFORMERS-A-to-K.html (replacement L302: 5 H at 200 mA); a Drip choke is reportedly 1.5 H; not printed on A-96039', genome: psu.l302_h}
