  load_ohm: {value: 600, source: '[MAN] p.4: 600 ohm output'}
  numerical_leak_ohm: {value: 1000000000.0, source: 'numerical: DC path for the floating T104 and T301 secondaries (not physical)'}
  r101_r102_ohm: {value: 360, source: 'sch: R101, R102 180 ohm 1% across each primary winding; primaries taken in series'}
  r103_r104_ohm: {value: 680, source: 'sch: R103, R104 680 1W, one per bank'}
